def matmul(a: list[list[float]], b: list[list[float]]) -> list[list[float]]:
    # Validate matrix a
    if not a:
        raise ValueError("Matrix a is empty")
    if not a[0]:
        raise ValueError("Matrix a has an empty row")
    rows_a = len(a)
    cols_a = len(a[0])
    for row in a:
        if not row:
            raise ValueError("Matrix a has an empty row")
        if len(row) != cols_a:
            raise ValueError("Matrix a is ragged")

    # Validate matrix b
    if not b:
        raise ValueError("Matrix b is empty")
    if not b[0]:
        raise ValueError("Matrix b has an empty row")
    rows_b = len(b)
    cols_b = len(b[0])
    for row in b:
        if not row:
            raise ValueError("Matrix b has an empty row")
        if len(row) != cols_b:
            raise ValueError("Matrix b is ragged")

    # Check inner dimensions match
    if cols_a != rows_b:
        raise ValueError("Inner dimensions do not match")

    # Perform matrix multiplication
    result = [[0.0 for _ in range(cols_b)] for _ in range(rows_a)]
    for i in range(rows_a):
        for j in range(cols_b):
            total = 0.0
            for k in range(cols_a):
                total += a[i][k] * b[k][j]
            result[i][j] = total
    return result
